#!/usr/bin/env node

/**
 * Generate ZJP_SNAPSHOT.json + ZJP_CONTEXT.md
 *
 * Reads metrics/latest.json (already generated by collect-metrics.js) and
 * local data files to produce a role-sectioned context file for Claude sessions.
 *
 * Output:
 *   .github/data/ZJP_SNAPSHOT.json  — machine-readable, committed to jobs-data-2026
 *   .github/data/ZJP_CONTEXT.md     — human+Claude-readable, committed alongside
 *
 * Run: called by collect-metrics.yml after collect-metrics.js completes.
 * Staleness: inherits from metrics/latest.json (max 6h old).
 */

const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(process.cwd(), '.github', 'data');
const METRICS_LATEST = path.join(DATA_DIR, 'metrics', 'latest.json');
const OPEN_DECISIONS_FILE = path.join(DATA_DIR, 'ZJP_OPEN_DECISIONS.md');
const SNAPSHOT_OUT = path.join(DATA_DIR, 'ZJP_SNAPSHOT.json');
const CONTEXT_OUT = path.join(DATA_DIR, 'ZJP_CONTEXT.md');

const STALE_HOURS = 2;

function readJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
}

function readOpenDecisions() {
  try {
    if (!fs.existsSync(OPEN_DECISIONS_FILE)) return [];
    return fs.readFileSync(OPEN_DECISIONS_FILE, 'utf8')
      .split('\n')
      .map(l => l.trim())
      .filter(l => l && !l.startsWith('#') && !l.startsWith('>'));
  } catch {
    return [];
  }
}

/**
 * Read enrichment stats directly from enrichment-stats.json as a fallback
 * when metrics/latest.json doesn't yet have the enrichment field.
 */
function readEnrichmentDirect() {
  try {
    const enrichPath = path.join(DATA_DIR, 'enrichment-stats.json');
    if (!fs.existsSync(enrichPath)) return null;
    const stats = JSON.parse(fs.readFileSync(enrichPath, 'utf8'));
    return {
      totalEnriched: stats.total_enriched ?? null,
      totalHasDescription: stats.total_has_description ?? null,
      totalTechUs: stats.total_tech_us ?? null,
    };
  } catch {
    return null;
  }
}

function formatAge(isoTimestamp) {
  const ageMs = Date.now() - new Date(isoTimestamp).getTime();
  const mins = Math.round(ageMs / 60000);
  if (mins < 60) return `${mins} min ago`;
  const hrs = Math.round(mins / 60);
  return `${hrs}h ago`;
}

function stalenessFlag(isoTimestamp) {
  const ageHours = (Date.now() - new Date(isoTimestamp).getTime()) / 3600000;
  if (ageHours < 0.5) return `🟢 Fresh (${formatAge(isoTimestamp)})`;
  if (ageHours < STALE_HOURS) return `🟡 Updating (${formatAge(isoTimestamp)})`;
  return `🔴 STALE (${formatAge(isoTimestamp)}) — pipeline may be down`;
}

function fmtNum(n) {
  if (n == null) return 'n/a';
  return Number(n).toLocaleString('en-US');
}

function fmtPct(n) {
  if (n == null) return '';
  return ` (${n > 0 ? '+' : ''}${n}%)`;
}

function repoStatusLine(name, r) {
  const status = r.workflowStatus === 'success' ? '✅' : r.workflowStatus === 'failure' ? '❌' : '⚠️';
  const jobs = r.jobCount != null ? `${fmtNum(r.jobCount)} jobs` : 'n/a (by design)';
  const stars = r.stars != null ? ` · ⭐${r.stars}` : '';
  return `${status} ${name}: ${jobs}${stars}`;
}

function main() {
  console.log('📸 Generating ZJP snapshot...');

  if (!fs.existsSync(METRICS_LATEST)) {
    console.error('❌ metrics/latest.json not found — run collect-metrics.js first');
    process.exit(1);
  }

  const metrics = readJson(METRICS_LATEST);
  if (!metrics) {
    console.error('❌ metrics/latest.json is not valid JSON');
    process.exit(1);
  }

  const openDecisions = readOpenDecisions();
  const generatedAt = new Date().toISOString();
  const metricsAge = metrics.timestamp;

  // ── Build snapshot JSON ──────────────────────────────────────────────────
  const snapshot = {
    meta: {
      generated_at: generatedAt,
      generated_by: 'generate-snapshot.js v1',
      metrics_timestamp: metricsAge,
      stale_if_older_than_hours: STALE_HOURS,
    },
    pool: {
      total: metrics.pipeline?.pipelineTotal ?? null,
      by_source: metrics.pipeline?.bySource ?? null,
      us_entry_level: metrics.pipeline?.tagStats?.usTagged ?? null,
      entry_level: metrics.pipeline?.tagStats?.entryLevel ?? null,
      interns: metrics.pipeline?.tagStats?.internship ?? null,
      by_domain: metrics.pipeline?.tagStats?.domains ?? null,
    },
    enrichment: metrics.enrichment ?? readEnrichmentDirect(),
    pipeline: {
      last_run_at: metricsAge,
      all_repos_operational: (metrics.summary?.failedRepos ?? 1) === 0,
      failed_repo_count: metrics.summary?.failedRepos ?? null,
    },
    repos: metrics.repos ?? {},
    growth: metrics.growth ?? null,
    open_decisions: openDecisions,
  };

  fs.writeFileSync(SNAPSHOT_OUT, JSON.stringify(snapshot, null, 2) + '\n');
  console.log(`  ✅ ZJP_SNAPSHOT.json written`);

  // ── Build ZJP_CONTEXT.md ─────────────────────────────────────────────────
  const p = snapshot.pool;
  const g = snapshot.growth;
  const wowLine = g && g.total_delta != null
    ? ` · WoW: ${g.total_delta > 0 ? '+' : ''}${fmtNum(g.total_delta)}${fmtPct(g.total_delta_pct)}`
    : '';

  const domainLines = p.by_domain
    ? Object.entries(p.by_domain)
        .sort(([, a], [, b]) => b - a)
        .map(([k, v]) => `${k}: ${fmtNum(v)}`)
        .join(' · ')
    : 'n/a';

  const sourceLines = p.by_source
    ? Object.entries(p.by_source)
        .sort(([, a], [, b]) => b - a)
        .map(([k, v]) => `${k}: ${fmtNum(v)}`)
        .join(' · ')
    : 'n/a';

  const repoLines = Object.entries(snapshot.repos)
    .map(([name, r]) => `  ${repoStatusLine(name, r)}`)
    .join('\n');

  const decisionsBlock = openDecisions.length > 0
    ? openDecisions.map(d => `- ${d}`).join('\n')
    : '- (none)';

  const enrichBlock = snapshot.enrichment
    ? `Enriched: ${fmtNum(snapshot.enrichment.totalEnriched)} · Has description: ${fmtNum(snapshot.enrichment.totalHasDescription)} · Tech US: ${fmtNum(snapshot.enrichment.totalTechUs)}`
    : 'n/a';

  const allOk = snapshot.pipeline.all_repos_operational;
  const pipelineStatus = allOk ? '✅ LIVE' : `⚠️ ${snapshot.pipeline.failed_repo_count} repo(s) failing`;

  const context = `# ZJP Context — ${generatedAt.replace('T', ' ').slice(0, 16)} UTC
> Generated by generate-snapshot.js. Source: metrics/latest.json (${formatAge(metricsAge)}).
> ${stalenessFlag(metricsAge)}

---

## SYSTEM STATUS (all roles read this)

| Item | Value |
|------|-------|
| Pipeline | ${pipelineStatus} |
| Pool total | ${fmtNum(p.total)}${wowLine} |
| US entry-level | ${fmtNum(p.us_entry_level)} |
| Interns (US) | ${fmtNum(p.interns)} |
| Enrichment | ${enrichBlock} |

---

## STRATEGIC (Strategist reads this)

**Pool by domain:**
${domainLines}

**Pool by source:**
${sourceLines}

**Open decisions needing input:**
${decisionsBlock}

---

## OPERATIONAL (Auditor reads this)

**Consumer repos:**
${repoLines}

**Week-over-week growth:** ${g ? `${g.total_delta > 0 ? '+' : ''}${fmtNum(g.total_delta)} jobs${fmtPct(g.total_delta_pct)} vs ${g.compared_to?.slice(0, 10)}` : 'insufficient history'}

**Source deltas (WoW):**
${g?.by_source_delta ? Object.entries(g.by_source_delta).map(([k, v]) => `${k}: ${v > 0 ? '+' : ''}${v}`).join(' · ') : 'n/a'}

---

## IMPLEMENTATION (Coder reads this)

**Next tasks:** See \`projects/zjp/TODO.md\` (not auto-generated)

**GH_PAT expiry:** 2026-05-30 — rotate by May 1

**Active blockers:** See open decisions above + \`projects/zjp/CURRENT_STATE.md\`

---

*Full machine-readable data: ZJP_SNAPSHOT.json (co-located)*
`;

  fs.writeFileSync(CONTEXT_OUT, context);
  console.log(`  ✅ ZJP_CONTEXT.md written`);
  console.log(`\n📸 Snapshot complete. Pool: ${fmtNum(p.total)} jobs. Metrics age: ${formatAge(metricsAge)}.`);
}

main();
